/// <summary>
/// Base class for PricingAttribute table <c>InventDim</c>
/// </summary>
internal abstract class GUPPricingAttributeInventDim_Product extends GUPAbstractPricingAttribute implements GUPIPricingAttribute
{

}

Method.Source:
    protected InventDim getTableRecord(Common _pricingObject)
    {
        InventDim inventDim;

        switch (_pricingObject.TableId)
        {
            case tableNum(SalesLine):
                SalesLine salesLine         = _pricingObject as SalesLine;
                inventDim                   = salesLine.inventDim();
                break;
            case tableNum(SalesQuotationLine):
                SalesQuotationLine sqLine   = _pricingObject as SalesQuotationLine;
                inventDim                   = sqLine.inventDim();
                break;
        }

        return inventDim;
    }

    protected QueryBuildDataSource getQueryBuildDatasource(Query _query, Map _qbdsMap = null)
    {
        QueryBuildDataSource qbdsRoot;

        if (_qbdsMap && _qbdsMap.exists(tableStr(InventDim)))
        {
            qbdsRoot = _qbdsMap.lookup(tableStr(InventDim));
        }
        else
        {
            qbdsRoot = _query.addDataSource(tableNum(InventDim));

            if (_qbdsMap)
            {
                _qbdsMap.insert(tableStr(InventDim), qbdsRoot);
            }
        }

        return qbdsRoot;
    }

    public Query buildPricingObjectQuery(Query _query, anytype _value, Map _qdbsMap = null)
    {
        QueryBuildDataSource qbds;

        qbds = this.getQueryBuildDatasource(_query, _qdbsMap);
        this.setQueryBuildDatasourceRange(qbds, _value);

        return _query;
    }
